<template><div class="clinic-layout"><section class="card queue"><div class="card-heading"><div><h2>患者队列</h2><p>按挂号顺序接诊</p></div><el-button icon="el-icon-refresh" circle @click="loadQueue"/></div><el-input v-model="search" placeholder="姓名 / 病历号" clearable prefix-icon="el-icon-search" @keyup.enter.native="loadQueue(1)"/><div class="queue-filter"><el-radio-group v-model="queueFilter" size="mini"><el-radio-button label="active">待诊 / 在诊</el-radio-button><el-radio-button label="all">全部</el-radio-button></el-radio-group></div><button v-for="e in visibleQueue" :key="e.id" class="patient-row" :class="{selected:detail&&detail.encounter.id===e.id}" @click="open(e)"><span class="patient-avatar">{{e.patient_name.slice(0,1)}}</span><span class="patient-row-copy"><b>{{e.patient_name}}</b><small>{{e.visit_no}}</small><small>{{e.department_name}} · {{e.doctor_name}}</small></span><Status :value="e.status"/></button><el-empty v-if="!visibleQueue.length" description="暂无符合条件的患者" :image-size="70"/><el-pagination small layout="total,prev,next" :total="queue.total" :page-size="20" :current-page.sync="page" @current-change="loadQueue"/></section><div v-if="detail" class="clinic-body" v-loading="loading"><section class="card patient-summary"><div class="person"><span class="patient-avatar large">{{detail.encounter.patient_name.slice(0,1)}}</span><div><h2>{{detail.encounter.patient_name}} <small>{{detail.encounter.gender}} · {{ageText}}</small></h2><p>{{detail.encounter.case_no}}　{{detail.encounter.settle_type}}</p><p>{{detail.encounter.department_name}} · {{date(detail.encounter.created_at)}}</p></div></div><div><Status :value="detail.encounter.status"/><el-button v-if="editable&&detail.diagnosis" plain @click="finish" class="finish-button">结束就诊</el-button></div></section>
  <section class="card"><el-tabs v-model="tab"><el-tab-pane label="病历首页" name="record"><el-form :disabled="!editable" label-position="top" class="form-grid"><el-form-item label="主诉 *" class="full"><el-input v-model="record.chief_complaint" type="textarea" :rows="2" maxlength="2000" placeholder="记录患者本次主要症状、体征与持续时间"/></el-form-item><el-form-item v-for="f in recordFields" :key="f.key" :label="f.name"><el-input v-model="record[f.key]" type="textarea" :rows="3" :maxlength="f.max||2000"/></el-form-item><el-form-item label="初步诊断 *"><el-select v-model="record.initial_diagnosis" filterable allow-create remote :remote-method="loadDiseases" default-first-option placeholder="搜索疾病或手动输入"><el-option v-for="d in diseases" :key="d.code" :label="`${d.code} ${d.name}`" :value="d.name"/></el-select></el-form-item><el-form-item label="检查 / 检验建议"><el-input v-model="record.suggestions" type="textarea" :rows="2" maxlength="2000"/></el-form-item><div class="form-actions full"><span class="muted">版本 {{record.version||0}} · 保存后进入看诊状态</span><el-button type="primary" :loading="saving" @click="saveRecord">保存病历</el-button></div></el-form></el-tab-pane>
  <el-tab-pane label="医技申请" name="orders"><el-alert title="检查和检验需先保存初步诊断；处置需先完成门诊确诊。" type="info" :closable="false"/><el-form label-position="top" class="section-gap" :disabled="!editable"><el-form-item label="项目类型"><el-radio-group v-model="orderKind" @change="selectedItemIds=[]"><el-radio-button label="CHECK">检查</el-radio-button><el-radio-button label="LAB">检验</el-radio-button><el-radio-button label="TREAT">处置</el-radio-button></el-radio-group></el-form-item><el-form-item label="选择项目（按编码或名称搜索，可多选）"><el-select v-model="selectedItemIds" multiple filterable placeholder="选择项目"><el-option v-for="i in serviceItems" :key="i.id" :value="i.id" :label="`${i.code} · ${i.name} · ${i.specification||''} · ${money(i.price_cents)}`"/></el-select></el-form-item><div class="form-grid"><el-form-item label="目的要求"><el-input v-model="order.purpose" maxlength="1000"/></el-form-item><el-form-item label="部位"><el-input v-model="order.body_part" maxlength="100"/></el-form-item><el-form-item label="备注" class="full"><el-input v-model="order.notes" maxlength="1000"/></el-form-item></div><div class="form-actions"><b>本次申请合计 {{money(orderTotal)}}</b><el-button type="primary" :loading="saving" @click="createOrders">提交申请</el-button></div></el-form><h3>本次已开立项目</h3><OrderTable :orders="detail.orders.filter(o=>['CHECK','LAB','TREAT'].includes(o.kind))" @cancel="cancelOrder" :editable="editable"/></el-tab-pane>
  <el-tab-pane label="门诊确诊" name="diagnosis"><el-form label-position="top" :disabled="!editable"><el-form-item label="确诊疾病 *"><el-select v-model="diagnosis.disease_name" filterable allow-create remote :remote-method="loadDiseases" default-first-option @change="diseaseChanged"><el-option v-for="d in diseases" :key="d.code" :value="d.name" :label="`${d.code} ${d.name}`"/></el-select></el-form-item><el-form-item label="疾病编码"><el-input v-model="diagnosis.disease_code" maxlength="32" placeholder="可选"/></el-form-item><el-form-item label="处理意见"><el-input v-model="diagnosis.opinion" type="textarea" :rows="5" maxlength="2000"/></el-form-item><div class="form-actions"><span class="muted">确诊后可以开立处方或处置</span><el-button type="primary" :loading="saving" @click="saveDiagnosis">提交确诊</el-button></div></el-form></el-tab-pane>
  <el-tab-pane label="开立处方" name="prescription"><div class="toolbar"><el-select v-model="medicineId" filterable placeholder="按药品编码、名称或拼音查询" :filter-method="filterMedicines"><el-option v-for="m in filteredMedicines" :key="m.id" :value="m.id" :label="`${m.code} · ${m.name} · ${m.unit} · 库存${m.stock}`"/></el-select><el-button type="primary" plain :disabled="!editable" @click="addDrug">添加药品</el-button></div><div v-for="(drug,index) in drugs" :key="drug.medicine_id" class="drug-editor"><div class="card-heading"><h3>{{drug.name}} <small>{{money(drug.price_cents)}} / {{drug.unit}}</small></h3><el-button type="text" class="danger-text" @click="drugs.splice(index,1)">移除</el-button></div><p class="muted">{{drug.manufacturer}} · {{drug.formulation}}</p><el-form :disabled="!editable" label-position="top" class="drug-fields"><el-form-item label="数量"><el-input-number v-model="drug.quantity" :min="1" :max="10000"/></el-form-item><el-form-item label="用法"><el-input v-model="drug.drug_usage" maxlength="80" placeholder="如：口服"/></el-form-item><el-form-item label="用量"><el-input v-model="drug.dosage" maxlength="80" placeholder="如：每次1片"/></el-form-item><el-form-item label="频次"><el-input v-model="drug.frequency" maxlength="80" placeholder="如：每日两次"/></el-form-item><el-form-item label="使用天数"><el-input-number v-model="drug.days" :min="1" :max="365"/></el-form-item><el-form-item label="用药嘱托"><el-input v-model="drug.notes" maxlength="1000"/></el-form-item></el-form><div class="text-right">金额 {{money(drug.price_cents*drug.quantity)}}</div></div><el-empty v-if="!drugs.length" description="添加药品后填写完整医嘱" :image-size="60"/><div class="form-actions"><b>处方合计 {{money(drugTotal)}}</b><el-button type="primary" :disabled="!editable||!drugs.length" :loading="saving" @click="prescribe">开立处方</el-button></div><h3>已开处方药品</h3><OrderTable :orders="detail.orders.filter(o=>o.kind==='DRUG')" @cancel="cancelOrder" :editable="editable"/></el-tab-pane>
  <el-tab-pane label="结果与费用" name="results"><div class="toolbar"><span class="muted">已开立项目与结果按本次就诊汇总</span><el-button icon="el-icon-refresh" @click="reloadDetail">刷新</el-button></div><OrderTable :orders="detail.orders" :editable="false"/><div v-for="r in results" :key="r.id" class="result-report"><div><span class="subtle-badge">{{label(r.kind)}}报告</span><b>{{r.item_name}}</b><span class="muted">{{date(r.result_at)}} · {{r.executor_name}}</span></div><pre>{{r.result_content}}</pre></div><el-empty v-if="!results.length" description="尚无已录入的执行结果" :image-size="60"/></el-tab-pane></el-tabs></section>
  </div><section v-else class="card empty-workspace"><el-empty description="从左侧选择本次就诊患者"/></section></div></template>
<script>
import{api,money,date,label,reason}from'../api';import Status from'../components/Status.vue';import OrderTable from'../components/OrderTable.vue';
const emptyRecord=()=>({chief_complaint:'',present_illness:'',treatment_history:'',past_history:'',allergy_history:'',physical_exam:'',initial_diagnosis:'',suggestions:'',version:0});
export default{components:{Status,OrderTable},props:['catalog','user'],data:()=>({loading:false,saving:false,search:'',queue:{items:[],total:0},page:1,queueFilter:'active',detail:null,tab:'record',record:emptyRecord(),diagnosis:{disease_code:'',disease_name:'',opinion:''},diseases:[],orderKind:'CHECK',selectedItemIds:[],order:{purpose:'',body_part:'',notes:''},medicineId:'',medicineQuery:'',drugs:[],recordFields:[{key:'present_illness',name:'现病史',max:4000},{key:'treatment_history',name:'现病治疗情况'},{key:'past_history',name:'既往史'},{key:'allergy_history',name:'过敏史'},{key:'physical_exam',name:'体格检查'}]}),computed:{visibleQueue(){return[...this.queue.items].filter(e=>this.queueFilter==='all'||!['COMPLETED','CANCELLED'].includes(e.status)).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));},editable(){return this.detail&&!['CANCELLED','COMPLETED'].includes(this.detail.encounter.status);},ageText(){const e=this.detail.encounter;if(e.birth_date)return`出生于 ${String(e.birth_date).slice(0,10)}`;return e.age!=null?`${e.age}岁`:'年龄未填';},serviceItems(){return this.catalog.items.filter(i=>i.active&&i.kind===this.orderKind);},orderTotal(){return this.serviceItems.filter(i=>this.selectedItemIds.includes(i.id)).reduce((s,i)=>s+Number(i.price_cents),0);},filteredMedicines(){const q=this.medicineQuery.toLowerCase();return this.catalog.medicines.filter(m=>m.active&&`${m.name}${m.code}${m.pinyin}`.toLowerCase().includes(q));},drugTotal(){return this.drugs.reduce((s,i)=>s+i.price_cents*i.quantity,0);},results(){return this.detail.orders.filter(o=>o.result_content);}},created(){this.loadQueue();this.loadDiseases('');},methods:{money,date,label,async loadQueue(page){if(typeof page==='number')this.page=page;try{this.queue=await api.get('/encounters',{params:{q:this.search,page:this.page}});}catch{}},async open(e){this.loading=true;try{this.detail=await api.get(`/encounters/${e.id}`);this.record={...emptyRecord(),...this.detail.record};this.diagnosis={disease_code:'',disease_name:'',opinion:'',...this.detail.diagnosis};this.drugs=[];this.selectedItemIds=[];}catch{}finally{this.loading=false;}},async reloadDetail(){if(this.detail)await this.open(this.detail.encounter);},async loadDiseases(q){try{this.diseases=await api.get('/diseases',{params:{q}});}catch{}},diseaseChanged(name){this.diagnosis.disease_code=this.diseases.find(d=>d.name===name)?.code||'';},async saveRecord(){this.saving=true;try{this.record=await api.put(`/encounters/${this.detail.encounter.id}/record`,this.record);this.$message.success('病历已保存');await this.reloadDetail();await this.loadQueue();}catch{}finally{this.saving=false;}},async saveDiagnosis(){this.saving=true;try{await api.post(`/encounters/${this.detail.encounter.id}/diagnosis`,this.diagnosis);this.$message.success('确诊已提交');await this.reloadDetail();await this.loadQueue();}catch{}finally{this.saving=false;}},async createOrders(){if(!this.selectedItemIds.length)return this.$message.warning('请至少选择一个项目');this.saving=true;try{await api.post('/orders',{encounter_id:this.detail.encounter.id,item_ids:this.selectedItemIds,...this.order});this.$message.success('申请已提交，等待窗口收费');await this.reloadDetail();}catch{}finally{this.saving=false;}},async cancelOrder(order){const r=await reason(this,'撤销未收费项目');if(!r)return;try{await api.post(`/orders/${order.id}/cancel`,{reason:r});await this.reloadDetail();this.$message.success('项目已撤销');}catch{}},filterMedicines(q){this.medicineQuery=q;},addDrug(){if(!this.medicineId)return this.$message.warning('请选择药品');if(this.drugs.some(d=>d.medicine_id===this.medicineId))return this.$message.warning('药品已在处方中');const m=this.catalog.medicines.find(m=>m.id===this.medicineId);this.drugs.push({medicine_id:m.id,name:m.name,unit:m.unit,manufacturer:m.manufacturer,formulation:m.formulation,price_cents:Number(m.price_cents),quantity:1,drug_usage:'',dosage:'',frequency:'',days:1,notes:''});this.medicineId='';},async prescribe(){if(this.drugs.some(d=>!d.drug_usage||!d.dosage||!d.frequency))return this.$message.warning('请填写每个药品的用法、用量和频次');this.saving=true;try{await api.post('/prescriptions',{encounter_id:this.detail.encounter.id,items:this.drugs});this.$message.success('处方已开立');await this.reloadDetail();}catch{}finally{this.saving=false;}},async finish(){try{await this.$confirm('结束后本次病历将只读，确认已完成全部业务？','结束就诊',{type:'warning'});await api.post(`/encounters/${this.detail.encounter.id}/finish`);await this.reloadDetail();await this.loadQueue();this.$message.success('本次就诊已结束');}catch{}}}};
</script>
